/* Overview images — embedded PNG (generate: node scripts/gen_overview_images.cjs) */
(function (w) {
  w.MM_OVERVIEW_IMAGES = {"overview-story1":"data:image/png;base64,","overview-story2":"data:image/png;base64,","overview-story3":"data:image/png;base64,"};
  w.MMOverviewImage = {
    render: function (slot, alt) {
      var uri = w.MM_OVERVIEW_IMAGES[slot];
      if (!uri) return "";
      return '<img class="overview-hero-img" src="' + uri + '" alt="' + (alt || "").replace(/"/g, "&quot;") + '" decoding="async">';
    }
  };
})(window);
